cache.Put("c", 3);                       // evicts b (a refreshed by Get)
Cj.Eq(cache.Get("b"), -1, "b evicted");
Cj.Eq(cache.Get("a"), 1, "a survives");
cache.Put("a", 10);                      // update refreshes recency too
cache.Put("d", 4);                       // evicts c
